import type {IssueStateReasonType, IssueStateType} from '@github-ui/issue-pr-state/constants'
import {onTrackingIssueChanged} from '@github-ui/code-scanning-tracking-section/tracking-issue-event'
import type {TrackingIssue as TrackingIssueEvent} from '@github-ui/code-scanning-shared/types/tracking-link'

import {AlertPageHeader} from '@github-ui/platform-patterns/AlertPageHeader'
import type {AlertStatus} from '@github-ui/platform-patterns/AlertPageHeader'

import {RelativeTime} from '@primer/react'
import {useEffect, useState} from 'react'

const STATUS_MAP: Partial<Record<string, AlertStatus>> = {
  open: 'open',
  fixed: 'fixed',
  dismissed: 'dismissed',
  in_pr: 'open',
  in_branch: 'open',
  unknown: 'open',
}

const STATUS_LABEL_MAP: Partial<Record<string, string>> = {
  in_pr: 'In pull request',
  in_branch: 'On branch',
}

type DismissalRequest = {
  requester: {
    user: {login: string}
  } | null
  resolution: string
  requestedAt: string
}

type TrackingIssue = {
  number: number
  state: IssueStateType
  stateReason: IssueStateReasonType
  repository: {
    name: string
    ownerLogin: string
  }
}

export type CodeScanningAlertShowHeaderProps = {
  alertTitle: string
  alertNumber: number
  backButtonUrl: string
  branchName: string | null
  status: string
  statusDate: string | null
  dismissalRequest: DismissalRequest | null
  trackingIssue: TrackingIssue | null
}

const toTrackingIssue = ({state, stateReason, ...rest}: TrackingIssueEvent) => ({
  ...rest,
  state: state.toUpperCase() as IssueStateType,
  stateReason: stateReason?.toUpperCase() as IssueStateReasonType,
})

export const CodeScanningAlertShowHeader = ({
  alertTitle,
  alertNumber,
  backButtonUrl,
  status,
  trackingIssue: initialTrackingIssue,
  statusDate,
  branchName,
  dismissalRequest,
}: CodeScanningAlertShowHeaderProps) => {
  const [trackingIssue, setTrackingIssue] = useState(initialTrackingIssue)

  useEffect(() => onTrackingIssueChanged(detail => setTrackingIssue(detail ? toTrackingIssue(detail) : null)), [])

  const label = STATUS_LABEL_MAP[status]

  return (
    <AlertPageHeader
      backButtonText="Code scanning alerts"
      backButtonUrl={backButtonUrl}
      title={alertTitle}
      alertNumber={alertNumber}
      status={STATUS_MAP[status] ?? 'open'}
      trackingIssue={trackingIssue ?? undefined}
      subtitle={branchName || label ? <Subtitle branchName={branchName} label={label ?? 'On branch'} /> : undefined}
      trailingMessage={dismissalRequest ? <TrailingMessage {...dismissalRequest} /> : undefined}
      timestamp={statusDate ? new Date(statusDate) : undefined}
    />
  )
}

const Subtitle = ({branchName, label}: {branchName: string | null; label: string}) =>
  branchName ? (
    <>
      {label} <span className="branch-name">{branchName}</span>
    </>
  ) : (
    label
  )

const TrailingMessage = ({requester, resolution, requestedAt}: DismissalRequest) => {
  if (!requester)
    return (
      <>
        Dismissal requested as {resolution} <RelativeTime datetime={requestedAt} />
      </>
    )

  return (
    <>
      <strong>{requester.user.login}</strong> requested to dismiss this as {resolution}{' '}
      <RelativeTime datetime={requestedAt} />
    </>
  )
}
